function selectStructure(key){const m=STRUCTURES[key];if(!m)return;selected=key;const same=Object.keys(STRUCTURES).filter(k=>STRUCTURES[k].layer===activeLayer),i=same.indexOf(key)+1;document.querySelector('#muscle-number').textContent=String(i).padStart(2,'0');document.querySelector('#muscle-name').textContent=m.name;document.querySelector('#muscle-meta').textContent=m.info;document.querySelector('#muscle-region').textContent=m.region.toUpperCase();document.querySelector('#muscle-view').textContent=(m.view||m.layer).toUpperCase();document.querySelector('#focus-button').disabled=false;document.querySelectorAll('.muscle-item').forEach(el=>el.classList.toggle('selected',el.dataset.key===key))}
function clearSelection(){selected=null;document.querySelector('#muscle-number').textContent='00';document.querySelector('#muscle-name').textContent='Select a structure';document.querySelector('#muscle-meta').textContent='Touch the illuminated body to begin.';document.querySelector('#muscle-region').textContent='—';document.querySelector('#muscle-view').textContent='—';document.querySelector('#focus-button').disabled=true;document.querySelectorAll('.muscle-item').forEach(el=>el.classList.remove('selected'))}
function focusSelected(){stopCameraTween();const targets=parts.filter(p=>p.userData.key===selected);if(!targets.length)return;const box=new THREE.Box3();targets.forEach(p=>box.expandByObject(p));const c=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()).length(),dir=camera.position.clone().sub(controls.target).normalize(),m=STRUCTURES[selected],distance=m?.group==='head'?1.5:Math.max(3.6,size*3.2);if(m?.group==='head'){controls.target.copy(c);camera.position.copy(c).addScaledVector(dir,distance);controls.update();return}tweenCamera(c.clone().addScaledVector(dir,distance),c)}
function focusHand(side,view='palmar-oblique'){const targets=parts.filter(p=>p.userData.replacementHand&&p.name.toLowerCase().includes(side));if(!targets.length)return false;const box=new THREE.Box3();targets.forEach(p=>box.expandByObject(p));const center=box.getCenter(new THREE.Vector3()),distance=Math.max(4,box.getSize(new THREE.Vector3()).length()*2.1),directions={palm:new THREE.Vector3(0,1,.08),dorsal:new THREE.Vector3(0,-1,.08),'palmar-oblique':new THREE.Vector3(side==='left'?-.48:.48,.82,.24),'dorsal-oblique':new THREE.Vector3(side==='left'?-.48:.48,-.82,.24)},direction=(directions[view]||directions.palm).normalize();stopCameraTween();camera.position.copy(center).addScaledVector(direction,distance);controls.target.copy(center);controls.update();return true}
function animate(){requestAnimationFrame(animate);const now=performance.now(),distance=camera.position.distanceTo(controls.target),proximity=THREE.MathUtils.clamp((18-distance)/10,0,1),globalWave=reducedMotion?0:Math.sin(now*.00125);for(const p of activeParts()){const direct=p.userData.key===selected,on=direct||(selected==='upper-arm-surface'&&/^(biceps|triceps|deltoid)$/.test(p.userData.key)),over=p===hovered,mode=p.userData.layer,luminous=p.material.userData.luminous||{base:.2,phase:0},flow=reducedMotion?0:globalWave*(.055+.075*proximity)+Math.sin(now*.00125+luminous.phase)*(.035+.075*proximity),base=mode==='bone'?0xa8dbe3:mode==='skin'?0x061824:0x071b25;if(p.userData.surfaceProxy){p.material.opacity=direct?(p.userData.key==='upper-arm-surface'?.035:.12):over?.10:.025;p.material.color.setHex(on?0xd6b76f:over?0x4e98a7:0x071b25);p.material.emissive.setHex(on?0x6c531f:over?0x0b7185:0x031820);p.material.emissiveIntensity=on?.24:over?.16:.04;continue}p.material.color.setHex(on?0xb59662:over?0x4e98a7:base);p.material.emissive.setHex(on?0x5c451f:over?0x0b7185:mode==='bone'?0x164d5c:mode==='skin'?0x07566d:0x063746);p.material.emissiveIntensity=on?.5+(reducedMotion?0:globalWave*.025):over?.42:luminous.base+flow;if(!lastLuminousSample[mode])lastLuminousSample[mode]={};lastLuminousSample[mode]={intensity:p.material.emissiveIntensity,distance,proximity,reducedMotion,at:now}}controls.update();renderer.render(scene,camera)}
function renderList(){const list=document.querySelector('#muscle-list'),keys=Object.keys(STRUCTURES).filter(k=>STRUCTURES[k].layer===activeLayer).sort((a,b)=>STRUCTURES[a].name.localeCompare(STRUCTURES[b].name));list.innerHTML=keys.map((k,i)=>{const m=STRUCTURES[k];return `<button class="muscle-item" data-key="${k}" data-group="${m.group}" data-search="${(m.name+' '+m.region).toLowerCase()}"><span class="idx">${String(i+1).padStart(2,'0')}</span><span><b>${m.name}</b><small>${m.region.toUpperCase()} · ${m.layer.toUpperCase()}</small></span><span class="arrow">↗</span></button>`}).join('');list.querySelectorAll('button').forEach(b=>b.onclick=()=>{selectStructure(b.dataset.key);viewport.scrollIntoView({behavior:'smooth',block:'center'})});filterList()}
function filterList(){const q=document.querySelector('#search').value.toLowerCase().trim(),g=document.querySelector('[data-filter].active')?.dataset.filter||'all';document.querySelectorAll('.muscle-item').forEach(el=>el.hidden=!(el.dataset.search.includes(q)&&(g==='all'||el.dataset.group===g)))}
